23	/// Endpoint role whose scheduler and remote metrics feed one load context.
24	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
25	pub enum RouterLoadSource {
26	    Decode,
27	    Aggregated,
28	    Prefill,
29	    Encode,
30	}
31	
32	impl RouterLoadSource {
33	    pub(crate) const fn metric_label(self) -> &'static str {
34	        match self {
35	            Self::Decode | Self::Aggregated => WORKER_TYPE_DECODE,
36	            Self::Prefill => WORKER_TYPE_PREFILL,
37	            Self::Encode => WorkerType::Encode.as_str(),
38	        }
39	    }
40	
41	    pub const fn from_worker_type(worker_type: WorkerType) -> Self {
42	        match worker_type {
43	            WorkerType::Decode => Self::Decode,
44	            WorkerType::Aggregated => Self::Aggregated,
45	            WorkerType::Prefill => Self::Prefill,
46	            WorkerType::Encode => Self::Encode,
47	        }
48	    }
49	
50	    pub(crate) fn from_worker_role_or_metric(
51	        worker_role: Option<WorkerType>,
52	        metric_worker_type: &'static str,
53	    ) -> Self {
54	        worker_role.map(Self::from_worker_type).unwrap_or_else(|| {
55	            if metric_worker_type == WORKER_TYPE_PREFILL {
56	                Self::Prefill
57	            } else {
58	                Self::Aggregated
59	            }
60	        })
61	    }
62	
63	    pub(crate) const fn monitors_sequence_load(self) -> bool {
64	        !matches!(self, Self::Encode)
65	    }
66	}
67	
68	const SCHEDULER_LOAD_CHANNEL_CAPACITY: usize = 256;
69	
70	#[derive(Debug)]
71	enum SchedulerLoadCommand {
72	    Single(SchedulerLoadSnapshot),
73	    Batch(Vec<SchedulerLoadSnapshot>),
74	}
75	
76	impl SchedulerLoadCommand {
77	    fn into_snapshots(self) -> Vec<SchedulerLoadSnapshot> {
78	        match self {
79	            Self::Single(snapshot) => vec![snapshot],
80	            Self::Batch(snapshots) => snapshots,
81	        }
82	    }
83	}
84	
85	struct SchedulerLoadShared {
86	    overflow: DashMap<WorkerWithDpRank, SchedulerLoadSnapshot>,
87	    overflow_wake: Notify,
88	    coalesced_commands: AtomicU64,
89	    unexpected_closed: AtomicU64,
90	}
91	
92	impl SchedulerLoadShared {
93	    fn new() -> Self {
94	        Self {
95	            overflow: DashMap::new(),
96	            overflow_wake: Notify::new(),
97	            coalesced_commands: AtomicU64::new(0),
98	            unexpected_closed: AtomicU64::new(0),
99	        }
100	    }
101	
102	    fn coalesce(&self, command: SchedulerLoadCommand) {
103	        for snapshot in command.into_snapshots() {
104	            self.overflow.insert(snapshot.worker, snapshot);
105	        }
106	        self.overflow_wake.notify_one();
107	
108	        let count = self.coalesced_commands.fetch_add(1, Ordering::Relaxed) + 1;
109	        if count.is_power_of_two() {
110	            tracing::warn!(
111	                coalesced_commands = count,
112	                "scheduler-load channel saturated; coalescing latest worker snapshots"
113	            );
114	        }
115	    }
116	
117	    fn record_unexpected_closed(&self) {
118	        let count = self.unexpected_closed.fetch_add(1, Ordering::Relaxed) + 1;
119	        if count.is_power_of_two() {
120	            tracing::error!(
121	                closed_publications = count,
122	                "scheduler-load channel closed before load-context cancellation"
123	            );
124	        }
125	    }
126	
127	    fn drain_overflow(&self, snapshots: &mut Vec<SchedulerLoadSnapshot>) {
128	        let workers = self
129	            .overflow
130	            .iter()
131	            .map(|entry| *entry.key())
132	            .collect::<Vec<_>>();
133	        for worker in workers {
134	            if let Some((_, snapshot)) = self.overflow.remove(&worker) {
135	                snapshots.push(snapshot);
136	            }
137	        }
138	    }
139	}
140	
141	/// Nonblocking scheduler-load publication handle owned by one routing load context.
142	#[derive(Clone)]
143	pub struct SchedulerLoadSender {
144	    tx: Option<mpsc::Sender<SchedulerLoadCommand>>,
145	    shared: Arc<SchedulerLoadShared>,
146	    source: RouterLoadSource,
147	    cancellation_token: CancellationToken,
148	}
149	
150	impl SchedulerLoadSender {
151	    pub(crate) fn disabled(
152	        source: RouterLoadSource,
153	        cancellation_token: CancellationToken,
154	    ) -> Self {
155	        Self {
156	            tx: None,
157	            shared: Arc::new(SchedulerLoadShared::new()),
158	            source,
159	            cancellation_token,
160	        }
161	    }
162	
163	    pub(crate) const fn metric_label(&self) -> &'static str {
164	        self.source.metric_label()
165	    }
166	
167	    pub fn publish(&self, snapshot: SchedulerLoadSnapshot) {
168	        self.try_publish(SchedulerLoadCommand::Single(snapshot));
169	    }
170	
171	    pub fn publish_batch(&self, snapshots: Vec<SchedulerLoadSnapshot>) {
172	        if snapshots.is_empty() {
173	            return;
174	        }
175	        self.try_publish(SchedulerLoadCommand::Batch(snapshots));
176	    }
177	
178	    pub fn is_enabled(&self) -> bool {
179	        self.tx.is_some()
180	    }
181	
182	    fn try_publish(&self, command: SchedulerLoadCommand) {
183	        let Some(tx) = &self.tx else {
184	            return;
185	        };
186	        match tx.try_send(command) {
187	            Ok(()) => {}
188	            Err(mpsc::error::TrySendError::Full(command)) => self.shared.coalesce(command),
189	            Err(mpsc::error::TrySendError::Closed(_)) => {
190	                if !self.cancellation_token.is_cancelled() {
191	                    self.shared.record_unexpected_closed();
192	                }
193	            }
194	        }
195	    }
196	}
197	
198	pub(crate) struct SchedulerLoadReceiver {
199	    rx: mpsc::Receiver<SchedulerLoadCommand>,
200	    shared: Arc<SchedulerLoadShared>,
201	}
202	
203	impl SchedulerLoadReceiver {
204	    pub(crate) async fn recv(&mut self) -> Option<Vec<SchedulerLoadSnapshot>> {
205	        loop {
206	            tokio::select! {
207	                command = self.rx.recv() => {
208	                    let mut snapshots = command?.into_snapshots();
209	                    self.shared.drain_overflow(&mut snapshots);
210	                    return Some(snapshots);
211	                }
212	                _ = self.shared.overflow_wake.notified() => {
213	                    let mut snapshots = Vec::new();
214	                    self.shared.drain_overflow(&mut snapshots);
215	                    if !snapshots.is_empty() {
216	                        return Some(snapshots);
217	                    }
218	                }
219	            }
220	        }
221	    }
222	}
223	
224	pub(crate) fn scheduler_load_channel(
225	    source: RouterLoadSource,
226	    cancellation_token: CancellationToken,
227	) -> (SchedulerLoadSender, SchedulerLoadReceiver) {
228	    scheduler_load_channel_with_capacity(
229	        source,
230	        cancellation_token,
231	        SCHEDULER_LOAD_CHANNEL_CAPACITY,
232	    )
233	}
234	
235	fn scheduler_load_channel_with_capacity(
236	    source: RouterLoadSource,
237	    cancellation_token: CancellationToken,
238	    capacity: usize,
239	) -> (SchedulerLoadSender, SchedulerLoadReceiver) {
240	    let (tx, rx) = mpsc::channel(capacity);
241	    let shared = Arc::new(SchedulerLoadShared::new());
242	    (
243	        SchedulerLoadSender {
244	            tx: Some(tx),
245	            shared: shared.clone(),
246	            source,
247	            cancellation_token,
248	        },
249	        SchedulerLoadReceiver { rx, shared },
250	    )
251	}
252	
253	/// Owns the load lifecycle for one typed routing endpoint.
254	///
255	/// Every selection and dispatch plane receives a clone of this context's
256	/// single endpoint [`Client`]. Decode, aggregated, and prefill contexts
257	/// are intentionally independent.
258	pub struct RoutingLoadContext {
259	    client: Client,
260	    source: RouterLoadSource,
261	    scheduler_load: SchedulerLoadSender,
262	    thresholds: LoadThresholdHandle,
263	    cancellation_token: CancellationToken,
264	    monitor: Option<KvWorkerMonitor>,
265	    _task_guard: Option<EngineContextGuard>,
266	}
267	
268	impl RoutingLoadContext {
269	    pub async fn start(
270	        client: Client,
271	        source: RouterLoadSource,
272	        thresholds: LoadThresholdHandle,
273	        parent_token: &CancellationToken,
274	        task_guard: Option<EngineContextGuard>,
275	    ) -> anyhow::Result<Arc<Self>> {
276	        let cancellation_token = parent_token.child_token();
277	        let (scheduler_load, monitor) = if source.monitors_sequence_load() {
278	            let (scheduler_load, scheduler_load_rx) =
279	                scheduler_load_channel(source, cancellation_token.child_token());
280	            let monitor = KvWorkerMonitor::new(
281	                client.clone(),
282	                source,
283	                scheduler_load_rx,
284	                thresholds.clone(),
285	                cancellation_token.child_token(),
286	                task_guard.clone(),
287	            );
288	            monitor.start_monitoring().await?;
289	            (scheduler_load, Some(monitor))
290	        } else {
291	            (
292	                SchedulerLoadSender::disabled(source, cancellation_token.child_token()),
293	                None,
294	            )
295	        };
296	
297	        Ok(Arc::new(Self {
298	            client,
299	            source,
300	            scheduler_load,
301	            thresholds,
302	            cancellation_token,
303	            monitor,
304	            _task_guard: task_guard,
